export type SlotNameNames = keyof (typeof SlotNameByName)

const slotNameByLowerName: Record<string, SlotName> = {};
for (const [k, v] of Object.entries(SlotNameByName)) {
  slotNameByLowerName[k.toLowerCase()] = v;
}

// parseSlotName resolves a member by name, case-insensitively, mirroring the Go
// Parse method. Returns undefined when the name is unknown.
export function parseSlotName(name: string): SlotName | undefined {
  return slotNameByLowerName[name.trim().toLowerCase()];
}
